/* prog25_balanced_multitype.c
 *
 * Reimplementation of the original binary's observable behaviour.
 * The program reads the first command‑line argument and checks whether the
 * parentheses, square brackets and curly braces are correctly balanced and
 * properly nested.  It prints either "BALANCED" or "UNBALANCED".
 *
 * The original binary ignored any characters that were not one of the six
 * bracket symbols, and treated a missing argument as an empty string.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

static int is_open(char c)
{
    return c == '(' || c == '[' || c == '{';
}

static int matches(char open, char close)
{
    return (open == '(' && close == ')') ||
           (open == '[' && close == ']') ||
           (open == '{' && close == '}');
}

/* Simple stack implementation – the maximum depth cannot exceed the length
   of the input string. */
static int check_balanced(const char *s)
{
    size_t len = strlen(s);
    char *stack = malloc(len + 1);          /* +1 for safety */
    size_t top = 0;                         /* number of elements */

    for (size_t i = 0; i < len; ++i) {
        char c = s[i];

        if (is_open(c)) {
            stack[top++] = c;               /* push */
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) {                 /* nothing to match */
                free(stack);
                return 0;                  /* unbalanced */
            }
            if (!matches(stack[top - 1], c)) {
                free(stack);
                return 0;                  /* mismatched pair */
            }
            --top;                          /* pop */
        }
        /* all other characters are ignored */
    }

    int balanced = (top == 0);
    free(stack);
    return balanced;
}

int main(int argc, char *argv[])
{
    const char *input;

    if (argc < 2) {
        /* No argument – treat as empty string (balanced). */
        input = "";
    } else {
        input = argv[1];
    }

    if (check_balanced(input)) {
        puts("BALANCED");
    } else {
        puts("UNBALANCED");
    }
    return 0;
}
